-- Local disposable clone only. Catalog/ACL snapshot; no application rows.
SELECT jsonb_build_object(
  'database_acl',(SELECT jsonb_build_array(pg_get_userbyid(d.datdba),(SELECT jsonb_agg(jsonb_build_array(pg_get_userbyid(x.grantor),CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,x.privilege_type,x.is_grantable) ORDER BY pg_get_userbyid(x.grantor),CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,x.privilege_type) FROM aclexplode(COALESCE(d.datacl,acldefault('d',d.datdba))) x)) FROM pg_database d WHERE datname=current_database()),
  'extensions',(SELECT jsonb_agg(jsonb_build_array(e.extname,e.extversion,n.nspname,pg_get_userbyid(e.extowner)) ORDER BY e.extname) FROM pg_extension e JOIN pg_namespace n ON n.oid=e.extnamespace),
  'rls',(SELECT jsonb_agg(jsonb_build_array(c.relname,c.relrowsecurity,c.relforcerowsecurity,pg_get_userbyid(c.relowner)) ORDER BY c.relname) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('r','p')),
  'sensitive_functions',(SELECT jsonb_agg(jsonb_build_array(n.nspname,p.proname,pg_get_function_identity_arguments(p.oid),p.prosecdef,md5(p.prosrc),pg_get_userbyid(p.proowner),r.rolname,has_function_privilege(r.oid,p.oid,'EXECUTE')) ORDER BY n.nspname,p.proname,pg_get_function_identity_arguments(p.oid),r.rolname) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace CROSS JOIN pg_roles r WHERE n.nspname IN ('public','private') AND p.proname IN ('app_is_admin','consume_business_card_rate_limit','register_business_card_event_with_token','mirror_legacy_nfc_event_to_business') AND r.rolname IN ('anon','authenticated','service_role')),
  'triggers',(SELECT jsonb_agg(jsonb_build_array(c.relname,t.tgname,t.tgenabled,pg_get_userbyid(p.proowner),p.proname) ORDER BY c.relname,t.tgname) FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_proc p ON p.oid=t.tgfoid WHERE n.nspname='public' AND NOT t.tgisinternal),
  'default_acl',(SELECT jsonb_agg(jsonb_build_array(pg_get_userbyid(d.defaclrole),n.nspname,d.defaclobjtype,(SELECT jsonb_agg(jsonb_build_array(pg_get_userbyid(x.grantor),CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,x.privilege_type,x.is_grantable) ORDER BY pg_get_userbyid(x.grantor),CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,x.privilege_type) FROM aclexplode(d.defaclacl) x)) ORDER BY pg_get_userbyid(d.defaclrole),n.nspname,d.defaclobjtype) FROM pg_default_acl d LEFT JOIN pg_namespace n ON n.oid=d.defaclnamespace),
  'columns',(SELECT jsonb_agg(jsonb_build_array(table_name,column_name,data_type,is_nullable,column_default,is_identity) ORDER BY table_name,ordinal_position) FROM information_schema.columns WHERE table_schema='public' AND table_name IN ('app_businesses','app_business_cards','app_profiles','app_business_members','app_business_events','app_business_review_snapshots','nfc_events','app_business_card_tokens')),
  'policies',(SELECT jsonb_agg(jsonb_build_array(tablename,policyname,cmd,roles,qual,with_check) ORDER BY tablename,policyname) FROM pg_policies WHERE schemaname='public'),
  'table_acl',(SELECT jsonb_agg(jsonb_build_array(c.relname,r.rolname,p.privilege,has_table_privilege(r.oid,c.oid,p.privilege)) ORDER BY c.relname,r.rolname,p.privilege) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN pg_roles r CROSS JOIN (VALUES ('SELECT'),('INSERT'),('UPDATE'),('DELETE'),('TRUNCATE'),('REFERENCES'),('TRIGGER'),('MAINTAIN')) p(privilege) WHERE n.nspname='public' AND c.relkind IN ('r','p') AND r.rolname IN ('anon','authenticated','service_role')),
  'column_acl',(SELECT jsonb_agg(jsonb_build_array(c.relname,a.attname,r.rolname,p.privilege,has_column_privilege(r.oid,c.oid,a.attnum,p.privilege)) ORDER BY c.relname,a.attnum,r.rolname,p.privilege) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_attribute a ON a.attrelid=c.oid CROSS JOIN pg_roles r CROSS JOIN (VALUES ('INSERT'),('UPDATE'),('REFERENCES')) p(privilege) WHERE n.nspname='public' AND c.relkind IN ('r','p') AND a.attnum>0 AND NOT a.attisdropped AND r.rolname IN ('anon','authenticated')),
  'sequence_acl',(SELECT jsonb_agg(jsonb_build_array(c.relname,r.rolname,p.privilege,has_sequence_privilege(r.oid,c.oid,p.privilege),s.seqincrement,s.seqmin,s.seqmax,s.seqcycle,pg_get_userbyid(c.relowner)) ORDER BY c.relname,r.rolname,p.privilege) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_sequence s ON s.seqrelid=c.oid CROSS JOIN pg_roles r CROSS JOIN (VALUES ('USAGE'),('SELECT'),('UPDATE')) p(privilege) WHERE n.nspname='public' AND r.rolname IN ('anon','authenticated','service_role'))
);
